import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/ATen.h>
#include <ATen/cuda/CUDAContext.h>

template <typename scalar_t>
__global__ void sigmoid_kernel(const scalar_t* __restrict__ in,
                               scalar_t* __restrict__ out,
                               size_t N) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N) {
        // Convert half to float, compute sigmoid, convert back
        float x = static_cast<float>(in[idx]);
        float y = 1.0f / (1.0f + expf(-x));
        out[idx] = static_cast<scalar_t>(y);
    }
}

// launch wrapper
torch::Tensor sigmoid_forward(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kFloat16, "input must be float16");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");

    auto output = torch::empty_like(input);
    const size_t N = input.numel();

    const int threads = 256;
    const int blocks = (N + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "sigmoid_cuda", ([&] {
        sigmoid_kernel<scalar_t><<<blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            N);
    }));

    // ensure kernel launch errors are caught
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel failed: ", cudaGetErrorString(err));
    }

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("sigmoid_forward", &sigmoid_forward, "Sigmoid forward (CUDA, fp16)");
}
'''

# compile the inline extension
sigmoid_ext = load_inline(name='sigmoid_ext',
                          cpp_sources='',
                          cuda_sources=src,
                          functions=['sigmoid_forward'],
                          verbose=False)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure tensor is fp16 and on CUDA; the kernel will assert otherwise.
        if not x.is_cuda:
            x = x.cuda()
        if x.dtype != torch.float16:
            x = x.to(torch.float16)
        return sigmoid_ext.sigmoid_forward(x)

# Example usage (can be removed in the actual test harness)
if __name__ == "__main__":
    batch_size = 4096
    dim = 393216
    x = torch.rand(batch_size, dim, dtype=torch.float16, device='cuda')
    model = ModelNew()
    y = model(x)
    # sanity check against torch.sigmoid
    torch.testing.assert_allclose(y, torch.sigmoid(x), atol=1e-3, rtol=1e-3)
    print("Kernel output matches torch.sigmoid")
